package com.academix.controller;
import com.academix.entity.ImportJob;import com.academix.importer.StudentFileImporter;import com.academix.repository.ImportJobRepository;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/imports") @RequiredArgsConstructor public class ImportController {private final StudentFileImporter importer;private final ImportJobRepository repository;@PostMapping public ImportJob upload(@RequestParam("file")MultipartFile file)throws Exception{return importer.run(file);}@GetMapping public Page<ImportJob> list(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return repository.findAll(PageRequest.of(page,Math.min(size,100),Sort.by(Sort.Direction.DESC,"startedAt")));}@GetMapping("/{id}") public ImportJob get(@PathVariable Long id){return repository.findById(id).orElseThrow();}}
